args.sparql:
SELECT DISTINCT ?father ?p ?label WHERE {
  ?father ?p <http://dbpedia.org/resource/Elizabeth_Capell,_Countess_of_Essex_(1704-1784)> .
  ?father rdf:type ?type .
  FILTER EXISTS { ?father rdf:type dbo:Person }
  OPTIONAL { ?father rdfs:label ?label }
} ORDER BY ?father

SELECT ?deathDate ?death WHERE {
  <http://dbpedia.org/resource/Wriothesley_Russell,_2nd_Duke_of_Bedford> dbo:deathDate ?deathDate .
  OPTIONAL { <http://dbpedia.org/resource/Wriothesley_Russell,_2nd_Duke_of_Bedford> rdfs:comment ?death . FILTER(lang(?death)='en') }
}

SELECT DISTINCT ?father ?fatherDeathDate WHERE {
  ?father dbp:issue ?issue .
  FILTER regex(str(?issue), "Elizabeth Russell", "i") .
  OPTIONAL { ?father dbo:deathDate ?fatherDeathDate }
}

SELECT DISTINCT ?father ?fatherDeathDate WHERE {
  ?father dbp:issue ?issue .
  FILTER regex(str(?issue), "Elizabeth Russell", "i") .
  OPTIONAL { ?father dbo:deathDate ?fatherDeathDate }
}

